/* Level 08 (Batalia) code following mobyutil; generated by tools/overlay_src.py, stubs replaced by C as functions are matched. Starts at 0x0026B0E8 (was mobyutil_0026B0E8.c). */
#include "common.h"
#include "callees.h"
#include "include_asm.h"

extern void set_identity_matrix(void *);
extern float fast_atan2(float, float);
extern void euler_to_matrix(void *, void *);
extern void fast_euler_to_matrix(void *, void *);
extern void transform_vector(void *, void *, void *);
extern void matrix_from_basis_rows(void *, void *);
extern void matrix_copy_rows(void *, void *);

/* Builds a matrix that rolls by roll around the direction dir and writes it to out. */
void build_axis_roll_matrix(void *out, void *dir, float roll) {
    float M[4][4];
    float Rz[4][4];
    float Ry[4][4];
    float Rx[4][4];
    float ang[4];
    float d[4];
    float a;
    qcopy(d, dir);
    set_identity_matrix(M);
    a = -fast_atan2(d[0], d[1]);
    ang[0] = 0.0f;
    ang[1] = 0.0f;
    ang[2] = a;
    euler_to_matrix(Rz, ang);
    transform_vector(d, d, Rz);
    a = -fast_atan2(d[2], d[0]);
    ang[0] = 0.0f;
    ang[2] = 0.0f;
    ang[1] = a;
    fast_euler_to_matrix(Ry, ang);
    transform_vector(d, d, Ry);
    ang[2] = roll;
    ang[0] = 0.0f;
    ang[1] = 0.0f;
    fast_euler_to_matrix(Rx, ang);
    sce_vu0_mul_matrix(M, Rz, M);
    sce_vu0_mul_matrix(M, Ry, M);
    sce_vu0_mul_matrix(M, Rx, M);
    matrix_from_basis_rows(Ry, Ry);
    sce_vu0_mul_matrix(M, Ry, M);
    matrix_from_basis_rows(Rz, Rz);
    sce_vu0_mul_matrix(M, Rz, M);
    qcopy(d, dir);
    transform_vector(d, d, M);
    matrix_copy_rows(out, M);
}
